import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_session_token(token):
    """Verify HMAC-based session token: base64(user_id):timestamp:signature"""
    try:
        parts = token.split(':')
        if len(parts) != 3:
            return None
        user_id, ts, sig = parts
        if abs(time.time() - int(ts)) > 3600:
            return None
        expected = hmac.new(SECRET.encode(), f"{user_id}:{ts}".encode(), hashlib.sha256).hexdigest()
        if hmac.compare_digest(expected, sig):
            return user_id
    except Exception:
        return None
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by name or department. Requires valid session."""
    auth = request.headers.get('X-Session-Token', '')
    caller = verify_session_token(auth)
    if not caller:
        return jsonify({'error': 'unauthorized'}), 401

    query_param = request.args.get('q', '')
    department = request.args.get('dept', '')

    # Build search query with filters
    base_query = "SELECT id, username, email, department FROM users WHERE 1=1"

    if query_param:
        # Search by username - using string formatting for LIKE pattern
        base_query += f" AND username LIKE '%{query_param}%'"

    if department:
        base_query += f" AND department = '{department}'"

    try:
        db = get_db()
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/users/<int:user_id>/profile', methods=['GET'])
def get_profile(user_id):
    """Get user profile by ID."""
    auth = request.headers.get('X-Session-Token', '')
    caller = verify_session_token(auth)
    if not caller:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    cursor = db.execute("SELECT id, username, email, department, role FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/admin/export', methods=['POST'])
def export_data():
    """Admin-only: export user data. Checks role from token."""
    auth = request.headers.get('X-Session-Token', '')
    caller = verify_session_token(auth)
    if not caller:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    cursor = db.execute("SELECT role FROM users WHERE id = ?", (caller,))
    row = cursor.fetchone()
    if not row or row['role'] != 'admin':
        return jsonify({'error': 'forbidden'}), 403

    table = request.json.get('table', 'users')
    # Restrict to allowed tables
    allowed = ['users', 'departments', 'audit_log']
    if table not in allowed:
        return jsonify({'error': 'invalid table'}), 400

    cursor = db.execute(f"SELECT * FROM {table}")
    results = [dict(row) for row in cursor.fetchall()]
    return jsonify({'data': results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
